    "passageText": "[Passage Context - Triple Passage: Corporate Supplier Sourcing, Product Specifications & Audit Report (Q181 - Q185)]\n[Document 1: Purchasing Sourcing Memo]\nTo: Manufacturing Procurement Team\nFrom: Clara Jensen, Director of Sourcing\nDate: May 5 | Subject: Sourcing Recyclable Packaging for Project EcoWrap\n\nOur consumer goods division is preparing to transition all product outer packaging to 100% biodegradable or recycled post-consumer cardboard by Q4. We are soliciting bids from certified sustainable paper mills. Key criteria:\n1. Minimum 85% certified post-consumer recycled fiber content (FSC certified)\n2. Water-based non-toxic soy inks for exterior branding graphics\n3. High burst strength rating (minimum 250 psi) to endure international parcel handling\n4. Guaranteed production capacity of at least 500,000 units per month\nTwo potential vendors have submitted samples for laboratory stress testing: GreenPack Industries and EcoTerra Packaging.\n\n[Document 2: Independent Testing Laboratory Report]\nVERITAS MATERIAL TESTING LABS — CERTIFICATE OF ANALYSIS\nReport #: VMT-8842 | Date: May 22 | Client: Pacific Consumer Goods\n\nSample A (GreenPack Industries - EcoCorrugated 300):\n• Recycled Content: 92% FSC-Certified post-consumer fiber\n• Ink Compatibility: Water-based soy inks applied with zero bleeding or smudging\n• Burst Strength: 275 psi (Exceeds 250 psi benchmark)\n• Unit Cost: $0.42 per box\n\nSample B (EcoTerra Packaging - BioShield Lite):\n• Recycled Content: 80% recycled fiber\n• Ink Compatibility: Solvent-based inks required (Soy ink adhesion failed test)\n• Burst Strength: 230 psi (Failed 250 psi benchmark)\n• Unit Cost: $0.36 per box\n\nLab Conclusion: Sample A (GreenPack Industries) fully meets all mechanical durability and environmental compliance standards. Sample B failed both the minimum recycled content threshold and burst resistance requirements.\n\n[Document 3: Purchase Order Email Confirmation]\nTo: sales@greenpackind.com | From: c.jensen@pacificcg.com\nDate: June 2 | Subject: Purchase Order #PO-99412 - EcoCorrugated 300\n\nDear GreenPack Sales Team,\nBased on the outstanding results of our independent laboratory stress analysis, Pacific Consumer Goods has selected GreenPack Industries as our exclusive primary supplier for Project EcoWrap packaging. Please find attached formal Purchase Order #PO-99412 for an initial production run of 600,000 units of EcoCorrugated 300 boxes at the agreed price of $0.42 per unit, totaling $252,000. Delivery should be made to our central distribution hub in Columbus, Ohio, in staggered bi-weekly shipments starting July 15. We look forward to a successful long-term collaboration.",
