    "passageText": "[Passage Context - Triple Passage: Commercial Banking Loan Application, Financial Audit & Loan Approval (Q196 - Q200)]\n[Document 1: Commercial Credit Loan Application]\nMERIDIAN COMMERCIAL BANK — LOAN APPLICATION #CR-2026-904\nApplicant: EcoLogistics Freight Corp | CEO: Marcus Sterling\nRequested Amount: $3,500,000 | Purpose: Fleet Electrification Expansion\nTerm: 7 Years (84 Months) | Collateral Offered: Commercial Depot Real Estate (Valued at $5.2M)\n\nBusiness Plan Summary:\nEcoLogistics plans to purchase twenty-five class-8 heavy-duty electric trucks and install four 350kW DC fast-charging depots to service regional distribution contracts with major retailers. The transition to electric haulage is projected to reduce fuel and maintenance overhead by $620,000 annually. Financial statements for the previous three fiscal years are attached for credit committee appraisal.\n\n[Document 2: Underwriting Risk & Audit Assessment]\nMERIDIAN CREDIT RISK COMMITTEE — INTERNAL AUDIT MEMO\nDate: March 12 | Applicant: EcoLogistics Freight Corp\n\nCredit Analysis:\n• Debt-Service Coverage Ratio (DSCR): 1.85 (Policy requires minimum 1.35 — Highly Favorable)\n• 3-Year Historical Revenue: $18.2M (2023), $21.4M (2024), $26.1M (2025) — Consistent 22% CAGR\n• Loan-to-Value (LTV) Ratio: 67.3% based on independent appraisal of the $5.2M commercial depot\n• Environmental Credit Subsidy: Qualifies for federal green transport credit, lowering interest rate by 0.75%\n\nRecommendation: Approve commercial loan request of $3,500,000 at a competitive floating interest rate of Prime + 1.25%, subject to standard quarterly financial covenant reporting.\n\n[Document 3: Formal Loan Commitment Letter]\nMERIDIAN COMMERCIAL BANK — LOAN COMMITMENT NOTICE\nTo: Marcus Sterling, CEO, EcoLogistics Freight Corp | Date: March 20\n\nDear Mr. Sterling,\nWe are delighted to inform you that the Meridian Commercial Credit Committee has officially approved your commercial loan facility in the amount of $3,500,000 for your fleet electrification project.\nLoan Terms Summary:\n• Principal Amount: $3,500,000 USD\n• Interest Rate: Fixed at 5.45% per annum (inclusive of the 0.75% green transport incentive discount)\n• Amortization Schedule: 84 equal monthly installments of $50,185\n• Closing & Funds Disbursement Date: April 15, 2026\nPlease review and sign the attached loan agreement documents and return them to our Commercial Lending Division by April 5 to finalize disbursement. Congratulations on advancing sustainable transport logistics.",
